def count_column_carries(left, right, base=10):
    if any(type(x) is not int for x in (left,right,base)) or left<0 or right<0 or not 2<=base<=36:
        raise ValueError('invalid digit addition')
    result=carry=0
    while left or right:
        carry=int(left%base+right%base>=base)
        result+=carry
        left//=base
        right//=base
    return result

def count_column_carries(left, right, base=10):
    if any(not isinstance(x,int) for x in (left,right,base)) or left<0 or right<0 or not 2<=base<=36:
        raise ValueError('invalid digit addition')
    result=carry=0
    while left or right:
        carry=int(left%base+right%base+carry>=base)
        result+=carry
        left//=base
        right//=base
    return result

def split_by_sizes(items, sizes):
    if any(type(size) is not int or size<0 for size in sizes) or sum(sizes)!=len(items):
        raise ValueError('invalid partition')
    result=[]
    start=0
    for size in sizes:
        if size: result.append(items[start:start+size])
        start+=size
    return result

